package com.hms.billing;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="tenant_subscriptions") public class TenantSubscription { @Id private UUID tenantId; @Column(nullable=false,length=80) private String planKey; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private SubscriptionStatus status; private LocalDate currentPeriodEnd; private Integer appointmentLimit; @Column(nullable=false) private OffsetDateTime updatedAt; protected TenantSubscription(){} public TenantSubscription(UUID tenantId,UpdateSubscriptionRequest r){this.tenantId=tenantId;apply(r);} public void apply(UpdateSubscriptionRequest r){planKey=r.planKey();status=r.status();currentPeriodEnd=r.currentPeriodEnd();appointmentLimit=r.appointmentLimit();updatedAt=OffsetDateTime.now();} public UUID getTenantId(){return tenantId;} public String getPlanKey(){return planKey;} public SubscriptionStatus getStatus(){return status;} public LocalDate getCurrentPeriodEnd(){return currentPeriodEnd;} public Integer getAppointmentLimit(){return appointmentLimit;} public OffsetDateTime getUpdatedAt(){return updatedAt;} }
